package com.tnc.tnc.arcana;
import com.tnc.tnc.life.routes.*;
import com.tnc.tnc.production.*;
import com.tnc.tnc.alchemy.*;
import com.tnc.tnc.adventure.AdventureGameTests;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.item.*;
import net.minecraft.world.InteractionHand;
import net.minecraftforge.gametest.*;
import java.util.*;

@GameTestHolder("tncarcana") @PrefixGameTestTemplate(false)
public final class FeedbackGameTests {
 private static RouteNodeEntity node(GameTestHelper h,BlockPos at,RouteKind kind,UUID owner){h.getLevel().setBlock(at,RouteContent.NODES.get(kind.id).get().defaultBlockState(),3);var n=(RouteNodeEntity)h.getLevel().getBlockEntity(at);n.owner=owner;RouteNetwork.add(h.getLevel(),at);return n;}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void towerReceivesFromSmallPoolThroughRoofCorner(GameTestHelper h){var owner=UUID.randomUUID();var at=h.absolutePos(new BlockPos(4,2,4));var tower=node(h,at,RouteKind.ABYSS_TOWER,owner);for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)for(int y=0;y<3;y++)if(x!=0||z!=0)h.getLevel().setBlock(at.offset(x,y,z),ArcanaContent.TOWER_BRICK.defaultBlockState(),3);var wire=node(h,at.offset(1,3,1),RouteKind.GOLD_WIRE,owner);var pool=node(h,at.offset(1,4,1),RouteKind.POOL,owner);pool.receive(100);((RouteWireBlock)wire.getBlockState().getBlock()).refresh(h.getLevel(),wire.getBlockPos());RouteNetwork.tickNetwork(h.getLevel());h.assertTrue(tower.mana>0&&pool.mana+tower.mana==100,"roof corner accepts real pool mana without storage ping pong");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=150) public static void forgeRearShellPortAndManualInputsDiscoverRecipe(GameTestHelper h){var owner=UUID.randomUUID();var at=h.absolutePos(new BlockPos(4,3,4));for(int i=0;i<27;i++)h.getLevel().setBlock(ForgeStructure.at(at,Direction.SOUTH,i),ForgeStructure.blockFor(ForgeStructure.expected(i)).defaultBlockState(),3);var f=(MagicForgeBlockEntity)h.getLevel().getBlockEntity(at);f.setOwner(owner);RouteNetwork.add(h.getLevel(),at);h.assertTrue(f.formed(),"valid forge");var wire=node(h,at.offset(0,0,-3),RouteKind.GOLD_WIRE,owner);var pool=node(h,at.offset(0,0,-4),RouteKind.POOL,owner);pool.receive(500);((RouteWireBlock)wire.getBlockState().getBlock()).refresh(h.getLevel(),wire.getBlockPos());RouteNetwork.tickNetwork(h.getLevel());h.assertTrue(f.charge()>0&&f.charge()+pool.mana==500,"fiber on rear brick powers controller conservatively");var recipe=f.recipes().stream().filter(r->r.category().equals("materials")&&r.workTicks()<=100&&!r.getId().getPath().contains("astral")).findFirst().orElseThrow();h.assertTrue(!f.knows(recipe.getId()),"empty recipe book before first craft");for(int i=0;i<recipe.inputs().size();i++){var input=recipe.inputs().get(i);f.setItem(i,input.ingredient().getItems()[0].copyWithCount(input.count()));}f.addCharge(2000);h.assertTrue(f.chosenRecipe()!=null,"manual inputs choose recipe without any sidebar click");h.runAfterDelay(110,()->{h.assertTrue(!f.getItem(4).isEmpty()&&f.knows(f.recipes().stream().filter(r->r.getResultItem(h.getLevel().registryAccess()).is(f.getItem(4).getItem())).findFirst().orElseThrow().getId()),"actual successful output unlocks recipe");h.succeed();});}
 @GameTest(template="building_test_empty",timeoutTicks=70) public static void wildWhaleWorksWithoutFoodOrHabitat(GameTestHelper h){var p=AdventureGameTests.player(h);var at=h.absolutePos(new BlockPos(3,2,3));p.teleportTo(at.getX(),at.getY(),at.getZ());var whale=com.tnc.tnc.life.pasture.PastureRegistry.TYPES.get("dewbound_whale").create(h.getLevel());whale.setPos(at.getX(),at.getY(),at.getZ());whale.setNoAi(true);h.getLevel().addFreshEntity(whale);var collector=node(h,at.east(2),RouteKind.ANIMAL_COLLECTOR,p.getUUID());h.assertTrue(whale.owner()==null&&whale.bindManaWork(p,collector.getBlockPos()),"wild animal binds with no food/taming requirement");collector.animal=whale.getUUID();h.runAfterDelay(60,()->{h.assertTrue(collector.mana+whale.storedResource()>0,"no food, no water habitat still produces real stored mana");h.assertTrue(!RouteNodeBlock.hasPanel(RouteKind.COLOR_TARGET)&&!RouteNodeBlock.hasPanel(RouteKind.ANIMAL_COLLECTOR),"binding targets have no unnecessary inventory UI");h.succeed();});}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void boundTapirProducesOffWorldTickBoundary(GameTestHelper h){h.runAfterDelay(h.getLevel().getGameTime()%20==0?1:0,()->{var p=AdventureGameTests.player(h);var at=h.absolutePos(new BlockPos(3,2,3));p.teleportTo(at.getX(),at.getY(),at.getZ());var a=com.tnc.tnc.life.pasture.PastureRegistry.TYPES.get("forgegill_tapir").create(h.getLevel());a.setPos(at.getX(),at.getY(),at.getZ());a.setNoAi(true);h.getLevel().addFreshEntity(a);h.assertTrue(a.bindManaWork(p,at.east(2)),"wild tapir binds");a.tickCount=20;a.aiStep();h.assertTrue(a.getPersistentData().getInt("WorkMana")==30,"first behavior pulse works even off absolute 400-tick boundary, without feed or warm habitat");a.aiStep();h.assertTrue(a.getPersistentData().getInt("WorkMana")==30,"same second cannot produce twice");h.succeed();});}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void physicalLidIsStoredAndReturnedOnBottling(GameTestHelper h){var p=AdventureGameTests.player(h);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);var at=h.absolutePos(new BlockPos(3,2,3));h.getLevel().setBlock(at,AlchemyContent.CAULDRON.defaultBlockState(),3);var pot=(AlchemyEntity)h.getLevel().getBlockEntity(at);pot.owner=p.getUUID();pot.addWater();for(var id:Elixir.SPRING.ingredients)pot.insert(new ItemStack(ArcanaContent.item(id)));pot.ignite(true);pot.temperature=450;pot.vortex_sync=80;p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ArcanaContent.item("sealing_lid")));pot.interact(p,InteractionHand.MAIN_HAND);h.assertTrue(pot.sealed&&p.getMainHandItem().isEmpty()&&pot.inventory.getItem(6).is(ArcanaContent.item("sealing_lid")),"lid is installed as a real item even without F8 enabled");var saved=pot.saveWithoutMetadata();pot.load(saved);h.assertTrue(pot.inventory.getItem(6).is(ArcanaContent.item("sealing_lid")),"installed lid survives save/load");pot.ready="spring";p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.GLASS_BOTTLE));pot.interact(p,InteractionHand.MAIN_HAND);h.assertTrue(!pot.sealed&&pot.inventory.getItem(6).isEmpty()&&p.getInventory().countItem(ArcanaContent.item("sealing_lid"))==1,"bottling returns exactly one lid");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void mealPairingsProduceRecognizablePortableDishes(GameTestHelper h){var n=node(h,h.absolutePos(new BlockPos(3,2,3)),RouteKind.MEAL_PLATE,UUID.randomUUID());String[][] pairs={{"dance_petal","hearth_pepper_fruit","sunpepper_roast"},{"hearth_pepper_fruit","stone_pattern_leaf","earthroot_loaf"},{"stone_pattern_leaf","homeward_flower_petal","moon_honey_parfait"},{"homeward_flower_petal","rainletter_berry","tide_herb_soup"},{"rainletter_berry","dance_petal","cloudleaf_salad"}};for(var pair:pairs){n.inventory.clearContent();n.inventory.setItem(0,new ItemStack(ArcanaContent.item(pair[0])));n.inventory.setItem(1,new ItemStack(ArcanaContent.item(pair[1])));var dish=ArcanaMeals.prepare(n);h.assertTrue(dish.is(ArcanaContent.item(pair[2]))&&dish.getTag().getList("MealIngredients",10).size()==2,"actual pair yields the right portable food and retains ingredients: "+pair[2]);}h.succeed();}

}
